      q('Enum lookup','What happens with `Level.valueOf("low")` for `enum Level { LOW, HIGH }`?',['It returns LOW','It throws IllegalArgumentException','It returns null','It does not compile'],1,'Enum name lookup is case-sensitive. No constant has the exact name low.'),
      q('Enum constructors','Which access modifier is allowed on an explicitly declared enum constructor?',['public','protected','private','public static'],2,'An enum constructor may be private or have no explicit access modifier. It cannot be public or protected.'),
      q('Enum collections','Which expression lists the constants in declaration order?',['Level.values()','Level.constants()','new Level[]()','Level.all()'],0,'Each enum declaration gets a generated static values() method that returns an array of its constants.')
