// One multiple-answer question per chapter, in addition to ten single-answer items.
const multipleAnswer = {
  ch01:q('Overloading','Which two differences can distinguish overloaded method parameter lists?',['Parameter types','Parameter names alone','Parameter count','Return type alone'],[0,2],'Overloading uses the parameter types and their order/count. Changing only names or return type does not create a distinct signature.'),
  ch02:q('Overriding','Which two changes can be legal in an overriding instance method?',['Reducing public access to private','Using a covariant reference return type','Adding an unrelated checked exception','Widening protected access to public'],[1,3],'An override can narrow a reference return type and widen access. It cannot reduce access or broaden the allowed checked exceptions.'),
  ch03:q('Record members','Which two can a record declare?',['An additional instance field','A static method','An implemented interface','An explicit superclass other than Record'],[1,2],'Records support static methods and interfaces. Their component state is restricted, and their superclass is fixed.'),
  ch04:q('Primitive types','Which two primitive types are integral types?',['char','float','boolean','long'],[0,3],'char and long are integral types. float is floating-point, and boolean is a distinct non-numeric primitive type.'),
  ch05:q('Java 21 switch','Which two statements are correct for Java 21?',['A switch can explicitly handle null','Every switch statement must return a value','Arrow rules fall through automatically','A pattern case can use a when guard'],[0,3],'Java 21 supports case null and guarded pattern cases. Arrow rules do not fall through; a switch statement need not return a value.'),
  ch06:q('List factories','Which two statements about `List.of("a", "b")` are correct in Java 21?',['Its elements can be replaced with set','It is unmodifiable','It accepts null elements','Its first element can be read with getFirst()'],[1,3],'List.of is unmodifiable and rejects nulls. The List interface supports getFirst in Java 21.'),
  ch07:q('Unchecked exceptions','Which two types are unchecked?',['IOException','IllegalStateException','AssertionError','SQLException'],[1,2],'RuntimeException subclasses and Error subclasses are unchecked. IOException and SQLException are checked exception types.'),
  ch08:q('Function signatures','Which two interface and method pairings are correct?',['Consumer<T> — accept(T)','Supplier<T> — apply(T)','Predicate<T> — get()','Function<T,R> — apply(T)'],[0,3],'Consumer consumes through accept; Function transforms through apply. Supplier uses get, and Predicate uses test.'),
  ch09:q('Terminal operations','Which two are terminal stream operations?',['filter','count','sorted','toList'],[1,3],'count and toList execute and consume the stream pipeline. filter and sorted are intermediate operations.'),
  ch10:q('Virtual threads','Which two statements about virtual threads in Java 21 are correct?',['They are daemon threads','They guarantee race-free access to shared data','They can run Runnable tasks','They require preview mode'],[0,2],'Virtual threads are daemon threads and execute Runnable tasks. They are final in Java 21 and do not eliminate data races.'),
  ch11:q('Date/time immutability','Which two are immutable?',['SimpleDateFormat','LocalDate','Calendar','DateTimeFormatter'],[1,3],'LocalDate and DateTimeFormatter are immutable. The legacy Calendar and SimpleDateFormat classes are mutable.'),
  ch12:q('Filesystem streams','Which two Files operations return streams that should be explicitly closed?',['lines(path)','readAllLines(path)','walk(path)','readString(path)'],[0,2],'Files.lines and Files.walk can retain filesystem resources. readAllLines and readString complete and close their file access internally.'),
  ch13:q('Service directives','Which two module directives are used for service consumption and provision?',['exports','uses','provides','opens'],[1,2],'uses identifies a consumed service. provides identifies an implementation supplied by the module; exports and opens are package-access directives.'),
  ch14:q('Locale-aware factories','Which two methods have an overload accepting a Locale?',['NumberFormat.getCurrencyInstance','MessageFormat.getCurrencyInstance','DateTimeFormatter.getCurrencyInstance','NumberFormat.getPercentInstance'],[0,3],'NumberFormat supplies locale-aware currency and percent factories. Neither of the other named classes has getCurrencyInstance.')
};
